"""Derive SkyyTrees/build_skyytrees_0.6.9.py from SkyyTrees 0.6.8 (build_skyytrees_0.6.8.py = the SET pin, itself GENERATED by
tools/trees_0_6_8_patch.py). Edit THIS patch, never the generated script. Every anchor is asserted once; at the end every change is undone on
a copy and compared with 0.6.8 (tools/soundpass_gen.Patch).
Run:
    python tools/trees_0_6_9_patch.py && python SkyyTrees/build_skyytrees_0.6.9.py && python SkyyTrees/test_skyytrees_0.6.9.py
"""
import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import soundpass_gen as G

NOTE = '''0.6.9 (2026-11-21) = LEAN MAP PICTURES - THE CLIENT TEXTURE ATLAS FITS AGAIN (round atlas1, part 1; Skyy 2026-11-21 "its a bit bugged" -
  the new Inventory screen drew red / white edges). Client log 2026-11-21 18-03: 912 x "Texture atlas rejected image" (SkyyTrees/Map 740,
  vanilla Common 46, SkyyGlass Clear / Separator ...): the SET's UI pictures (~76 Mpx, SkyyTrees 35.1 of it) overflowed the client's UI atlas,
  and every picture that did not fit draws as a red / white missing texture. No Java change but the version.
  1. THE MAP BASE (the grey dotted lines + junction diamonds of a whole map, one picture per layout = 11 x 1680 x 1548 @2x = 28.6 Mpx, 82 %
     of our map area) ships at 1x (Base.png, no @2x) cut to the box that holds its dots (even canvas px, so every zoom places it on whole
     pixels): 11 pictures, ~4.9 Mpx. The 1x picture is the 2 x 2 average of the old @2x one (premultiplied), = what the client showed at
     100 %; at 150 / 200 % the grey dots are stretched from it (a touch softer); the gold lit lines (E<k>@2x), the nodes, hubs, halo and
     emblem keep their @2x pictures (crisp, proven M3). The base element keeps its id (SkyyTrMBs) and its place in the page data; only its
     Anchor is the cut box (x the zoom) - every dot lands on the same canvas pixel as before (checked: the cut box holds every non-clear pixel).
  2. Build-time checks: every texture path of every page data file (L<n>Z<z>[K].txt) and of the kit's map textures is in the jar (as .png or
     @2x.png); the map area before / after printed; Trees' UI picture area at most 40 % of 0.6.8's (35.1 Mpx -> about 11.4).
  The pack-wide check is tools/ci/ui_budget.py (lint: WARN above 45 Mpx, FAIL above 60 Mpx for the SET's UI pictures; unproven).
  SAVED DATA: none. ROLLBACK to 0.6.8: alone (the atlas overflows again while SkyyShards is 0.4.25+; nothing else).
'''

P = G.Patch(os.path.join(ROOT, "SkyyTrees", "build_skyytrees_0.6.8.py"), os.path.join(ROOT, "SkyyTrees", "build_skyytrees_0.6.9.py"))
if "--out" in sys.argv:
    P.dst = os.path.abspath(sys.argv[sys.argv.index("--out") + 1])
assert P.has('VERSION = "0.6.8"') and P.has("0.6.8 (2026-11-21) = THE SICKLE RIGHT SWING") and not P.has("0.6.9 (2026-11-21)"), "not the generated SkyyTrees 0.6.8 script"
REG0, SYS0, CLS0, M0 = P.s.count("registerCommand("), P.s.count("registerSystem("), P.s.count("makeClass("), P.s.count("\nM(")

P.rep('''"""SkyyTrees 0.6.8 - build script (javassist via jpype, tools/skyybuild.py). Owner: Skyy (they/them).
GENERATED by tools/trees_0_6_8_patch.py from build_skyytrees_0.6.7.py (the SET pin) - edit the patch, not this file.
''', '''"""SkyyTrees 0.6.9 - build script (javassist via jpype, tools/skyybuild.py). Owner: Skyy (they/them).
GENERATED by tools/trees_0_6_9_patch.py from build_skyytrees_0.6.8.py (the SET pin) - edit the patch, not this file.
''' + NOTE + '''
SkyyTrees 0.6.8 - GENERATED by tools/trees_0_6_8_patch.py from build_skyytrees_0.6.7.py:
''')
P.rep('VERSION = "0.6.8"', 'VERSION = "0.6.9"')

# 1. the base picture: 1x, cut to its dots (replaces the @2x full-canvas ship)
P.rep('''for L_, lay_ in enumerate(TM_LAY):
    tm_ship(TM_LNAME[L_] + "/Base", SMAP.base_picture(lay_))
''', '''TM_BCUT = []              # 0.6.9: per layout the base picture's box (l, t, w, h) in 100 % canvas px (even numbers)
TM_BASE_OLD = 0           # 0.6.9: the 0.6.8 base area (px of the @2x full canvas) - for the printout


def tm_half(pic):
    """0.6.9: the 2 x 2 average (premultiplied alpha) of an @2x picture = the 1x picture the client showed at 100 %"""
    w_, h_, W_ = pic.w // 2, pic.h // 2, pic.w
    src, out = pic.px, SMAP.Pic(pic.w // 2, pic.h // 2)
    dst, al = out.px, pic.px[3::4]
    for y_ in range(h_):
        r0_, r1_ = 2 * y_ * W_, (2 * y_ + 1) * W_
        if al[r0_:r0_ + W_].count(0) == W_ and al[r1_:r1_ + W_].count(0) == W_:
            continue
        for x_ in range(w_):
            ps_ = (r0_ + 2 * x_, r0_ + 2 * x_ + 1, r1_ + 2 * x_, r1_ + 2 * x_ + 1)
            sa_ = al[ps_[0]] + al[ps_[1]] + al[ps_[2]] + al[ps_[3]]
            if not sa_:
                continue
            o_ = (y_ * w_ + x_) * 4
            for ch_ in range(3):
                dst[o_ + ch_] = int((sum(src[p_ * 4 + ch_] * al[p_] for p_ in ps_) + sa_ // 2) // sa_)
            dst[o_ + 3] = (sa_ + 2) // 4
    return out


def tm_cut(pic):
    """0.6.9: (the picture cut to its non-clear pixels, its box (l, t, w, h)) - the box on even px (whole pixels at 150 %)"""
    al, W_ = pic.px[3::4], pic.w
    rows = [y_ for y_ in range(pic.h) if al[y_ * W_:(y_ + 1) * W_].count(0) != W_]
    assert rows, "0.6.9: an empty map base"
    cols = [x_ for x_ in range(W_) if any(al[y_ * W_ + x_] for y_ in rows)]
    l_, t_, r_, b_ = cols[0], rows[0], cols[-1] + 1, rows[-1] + 1
    l_, t_, r_, b_ = l_ - l_ % 2, t_ - t_ % 2, min(W_, r_ + r_ % 2), min(pic.h, b_ + b_ % 2)
    assert l_ % 2 == 0 and t_ % 2 == 0 and r_ % 2 == 0 and b_ % 2 == 0, (l_, t_, r_, b_)
    out = SMAP.Pic(r_ - l_, b_ - t_)
    for y_ in range(t_, b_):
        out.px[(y_ - t_) * out.w * 4:(y_ - t_ + 1) * out.w * 4] = pic.px[(y_ * W_ + l_) * 4:(y_ * W_ + r_) * 4]
    assert sum(1 for a_ in out.px[3::4] if a_) == sum(1 for a_ in al if a_), "0.6.9: the cut lost a pixel"
    return out, (l_, t_, r_ - l_, b_ - t_)


for L_, lay_ in enumerate(TM_LAY):
    _b2 = SMAP.base_picture(lay_)
    TM_BASE_OLD += _b2.w * _b2.h
    _b1, _bx = tm_cut(tm_half(_b2))
    assert _b2.w == 2 * lay_["W"] and _b2.h == 2 * lay_["H"] and lay_["W"] % 2 == 0 and lay_["H"] % 2 == 0, TM_LNAME[L_]
    _bn = TM_LNAME[L_] + "/Base"
    _jp = TM_JAR + TM_DIR + _bn + ".png"            # 1x: no @2x file (the markup path is the same as 0.6.8's)
    assert _jp not in TM_ASSETS and "_" not in _bn
    TM_ASSETS[_jp] = SMAP.png(_b1)
    TM_PATHS[_bn] = TM_DIR + _bn + ".png"
    SUI.register_map_textures([TM_PATHS[_bn]])
    TM_BCUT.append(_bx)
for L_, lay_ in enumerate(TM_LAY):
''')

# the base element's Anchor = the cut box x the zoom (whole px: even box x 1 / 1.5 / 2)
P.rep('''        assert all(n_["pre"].endswith('"' + TM_DIR + "Node/") for n_ in nm_.nodes), "0.5.0: node pictures under Map/Node/"
''', '''        assert all(n_["pre"].endswith('"' + TM_DIR + "Node/") for n_ in nm_.nodes), "0.5.0: node pictures under Map/Node/"
        # 0.6.9: the base picture is cut to its dots - its element sits on the cut box (x the zoom); same id, same place in the list
        _bp0 = ("#" + TMP + "Cv", SUI.map_pic(TMP + "Bs", 0, 0, lz_["W"], lz_["H"], TM_PATHS[TM_LNAME[L_] + "/Base"]))
        assert nm_.static[0] == _bp0, "0.6.9: the kit's first static element is the full-canvas base: %s" % (nm_.static[0],)
        assert lz_["W"] == int(round(lay_["W"] * z_)) and lz_["H"] == int(round(lay_["H"] * z_)), "0.6.9: canvas x zoom"
        _bq = [v_ * z_ for v_ in TM_BCUT[L_]]
        assert all(abs(v_ - round(v_)) < 1e-9 for v_ in _bq), "0.6.9: the base box on whole px at %s: %s" % (z_, _bq)
        _bq = [int(round(v_)) for v_ in _bq]
        assert _bq[0] + _bq[2] <= lz_["W"] and _bq[1] + _bq[3] <= lz_["H"], "0.6.9: the base box inside the canvas"
        nm_.static[0] = (_bp0[0], SUI.map_pic(TMP + "Bs", _bq[0], _bq[1], _bq[2], _bq[3], TM_PATHS[TM_LNAME[L_] + "/Base"]))
''')

# the area printout + the texture references of the files the jar is built from (before B.assemble, so 'assembled' stays the last line;
# the jar is compared with TM_ASSETS byte for byte right after)
P.rep('''B.assemble(jar, m, OUT, dict(dict(dict(SWING_FILES, **_kit), **TM_ASSETS), **NI_FILES))''', '''# 0.6.9: every texture a map page names is in the jar files (as <path>.png or <path>@2x.png); the UI picture area
_tfiles = dict(dict(dict(SWING_FILES, **_kit), **TM_ASSETS), **NI_FILES)
_trefs = set()
for _p, _b in sorted(TM_ASSETS.items()):
    if _p.startswith(TM_RES) and _p.endswith(".txt"):
        _trefs.update(re.findall(r'"(SkyyTrees/Map/[A-Za-z0-9/]+)\\.png"', _b.decode("utf-8")))
_trefs.update(p_[:-4] for p_ in TM_PATHS.values())
_tmiss = sorted(r_ for r_ in _trefs if TM_JAR + r_ + ".png" not in _tfiles and TM_JAR + r_ + "@2x.png" not in _tfiles)
assert not _tmiss and len(_trefs) > 1000, "0.6.9: map textures the jar lacks: %s (%d refs)" % (_tmiss[:10], len(_trefs))
_tarea = _tcnt = 0
for _p, _b in _tfiles.items():
    if _p.startswith("Common/UI/Custom/") and _p.endswith(".png"):
        _w, _h = SMAP.png_size(_b)
        _tarea += _w * _h
        _tcnt += 1
_mold = TM_BASE_OLD + sum(SMAP.png_size(b_)[0] * SMAP.png_size(b_)[1] for p_, b_ in TM_ASSETS.items() if p_.endswith(".png") and not p_.endswith("/Base.png"))
_mnew = sum(SMAP.png_size(b_)[0] * SMAP.png_size(b_)[1] for p_, b_ in TM_ASSETS.items() if p_.endswith(".png"))
print("0.6.9 lean map pictures: bases %.2f -> %.2f Mpx (%d x 1x, cut); map pictures %.2f -> %.2f Mpx; UI pictures of the jar %d files, %.2f Mpx "
      "(0.6.8: 1302 files, 35.09 Mpx; -%.0f %%); %d map texture refs, all in the jar" % (
          TM_BASE_OLD / 1e6, sum(w_ * h_ for _l, _t, w_, h_ in TM_BCUT) / 1e6, len(TM_BCUT), _mold / 1e6, _mnew / 1e6, _tcnt, _tarea / 1e6,
          100.0 * (1 - _tarea / 35091796.0), len(_trefs)))
assert _tarea <= 0.40 * 35091796, "0.6.9: the UI picture area must drop by at least 60 %% (now %.2f Mpx)" % (_tarea / 1e6)
B.assemble(jar, m, OUT, _tfiles)''')

assert P.s.count("registerCommand(") == REG0 and P.s.count("registerSystem(") == SYS0 and P.s.count("makeClass(") == CLS0 and P.s.count("\nM(") == M0, "0.6.9: no new class / system / command / method"
P.finish()
print("wrote", P.dst)
